249	                + "\"segments\":[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]}";
250	        ApiResult first = postJson("/api/documents", body);
251	        assertThat(first.status()).isEqualTo(201);
252	
253	        // 同键同参：重放原结果，不产生新文档
254	        ApiResult replay = postJson("/api/documents", body);
255	        assertThat(replay.status()).isEqualTo(201);
256	        assertThat(replay.body().get("documentId").asLong())
257	                .isEqualTo(first.body().get("documentId").asLong());
258	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM document", Integer.class)).isEqualTo(1);
259	
260	        // 同键异参：409
261	        String different = "{\"requestId\":\"" + requestId + "\",\"targetLanguages\":[\"en\",\"ja\"],"
262	                + "\"segments\":[]}";
263	        ApiResult conflict = postJson("/api/documents", different);
264	        assertThat(conflict.status()).isEqualTo(409);
265	
266	        // 失败不占键：先以某 requestId 触发 422，再用同键修正参数后成功
267	        String failKey = newRequestId();
268	        ApiResult failed = postJson("/api/documents",
269	                "{\"requestId\":\"" + failKey + "\",\"targetLanguages\":[\"en\",\"en\"],\"segments\":[]}");
270	        assertThat(failed.status()).isEqualTo(422);
271	        ApiResult retried = postJson("/api/documents",
272	                "{\"requestId\":\"" + failKey + "\",\"targetLanguages\":[\"en\"],\"segments\":[]}");
273	        assertThat(retried.status()).isEqualTo(201);
274	    }
275	}
