            assertThat(release.body().get("segments").get(0).get("translation")
                    .get("content").asText()).isEqualTo("v3");
        } else {
            // 修订先成功：409（草稿版本变化）或 422（版本读取到 V2 而签署仍指向 V1），均不得发布
            assertThat(publishedVersion).isZero();
        }
    }
}

